@startuml

class Animal {
  + Identifier : int
  + Name : string
  + Breed : string
}

class Owner {
  + Identifier : int
  + Name : string
  + Address : string
  + PhoneNumber : string
}

class Breed {
  + Name : string
}

class Physician {
  + Identifier : int
  + Name : string
  + Address : string
  + PhoneNumber : string
}

class Appointment {
  + StartDateTime : datetime
}

class Condition {
  + CommonName : string
  + ScientificName : string
}

Owner "0..1" -- "0..*" Animal : owns
Animal "0..*" -- "1" Breed : belongs to
Breed "1" -- "0..*" Condition : common to
Physician "1" -- "0..*" Appointment : responsible for
Animal "1" -- "0..*" Appointment : attends
Owner "1" -- "0..*" Appointment : attends

@enduml

